fn trunc_len(n: usize, m: usize) -> usize {
    if m == 0 {
        // no truncation
        n
    } else if n > m {
        // drop exactly m elements
        n - m
    } else {
        // if m >= n, always return at least one element
        1
    }
}

fn legder(c: Vec<f64>, m: u8, _scl: f64) -> Vec<f64> {
    let n = c.len();
    let m_usize = m as usize;
    let len = trunc_len(n, m_usize);
    // take the first `len` elements, preserving their order
    c.into_iter().take(len).collect()
}

